<script setup lang="ts">import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import type{OrderProjection}from'../../domain/types';const p=ref<OrderProjection|null>(null),orderRef=ref(''),error=ref('');const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));const resultTitle=computed(()=>p.value?.facts.delivery==='CONFIRMED'?'充值已完成':p.value?.facts.delivery==='CONFLICT'?'需要协助':'充值处理中');async function refresh(){if(!orderRef.value)return;error.value='';try{p.value=await api.getProjection(orderRef.value)}catch{error.value='暂时无法更新订单，请稍后重试。'}}onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})</script>
<template><view class="page"><AppHeader left="订单" @left="uni.navigateBack()"/><view class="content"><view class="result"><text class="result-icon">⌛</text><view class="heading" role="heading" aria-level="1">{{resultTitle}}</view><text>我们正在确认结果，请勿重复充值</text></view><StatusNotice v-if="error" tone="risk" title="暂时无法更新">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready" tone="unknown" title="信息已更新">请刷新后查看最新内容。</StatusNotice><view class="card"><view class="kv"><text>充值号码</text><text>{{p?.maskedPhone||'待确认'}}</text></view><view class="kv"><text>到账金额</text><text>{{p?.productName||'待确认'}}</text></view><view class="kv"><text>实付金额</text><text>{{p?.total?.currency||''}} {{p?.total?(p.total.minor/100).toFixed(2):'待确认'}}</text></view></view><view class="timeline"><view class="done"><text class="dot"/><view><text>付款成功</text><small>付款结果已确认</small></view></view><view class="current"><text class="dot"/><view><text>正在处理充值</text><small>请勿重复充值</small></view></view><view><text class="dot"/><view><text>确认到账</text><small>结果确认后更新</small></view></view></view><button class="help" @click="uni.navigateTo({url:'/pages/support/case'})">需要帮助？联系我们</button></view><view class="action"><button class="secondary" @click="refresh">刷新进度</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.result{text-align:center;padding:12rpx 0}.result-icon{display:block;width:108rpx;height:108rpx;line-height:108rpx;margin:auto;border-radius:50%;background:#fff0d4;font-size:46rpx}.result .heading{font-size:46rpx}.result>text:last-child{color:var(--muted)}.timeline{margin:42rpx 16rpx 0}.timeline>view{position:relative;display:flex;padding-bottom:42rpx}.dot{width:24rpx;height:24rpx;margin:4rpx 30rpx 0 0;border-radius:50%;background:#d4dae3}.done .dot,.current .dot{background:var(--brand)}.timeline view view text,.timeline small{display:block}.timeline small{color:var(--muted);margin-top:6rpx}.help{display:block;margin:10rpx auto;color:var(--brand);font-weight:700}</style>
